import{z as l,x as A,o,c as p,q as r,j as i,D as n,d as E,s as m,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"zone map 与跳过索引","description":"","frontmatter":{"title":"zone map 与跳过索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zone-maps.md","filePath":"cs/zone-maps.md","lastUpdated":1791413859000}'),B={name:"cs/zone-maps.md"};function d(C,a,D,u,x,z){const t=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="zone-map-与跳过索引" tabindex="-1">zone map 与跳过索引 <a class="header-anchor" href="#zone-map-与跳过索引" aria-label="Permalink to &quot;zone map 与跳过索引&quot;">​</a></h1><div class="epigraph"><p>每个区记录 min/max 或粗过滤器；谓词与区无交则整区不读。这是统计，不是第二种 B+。</p><footer>—— 据 Oracle Exadata storage index；C-Store / Vertica 分区统计；Parquet 页统计</footer></div><p><a href="/cs/parquet-orc">上一课</a>在文件 footer 里放了统计。本课不背 Thrift 字段。缺口是库内表同样需要<strong>跳过</strong>：按块、按分区、按 row group 维护 zone map（区图）。选择率低且数据按谓词列部分有序或聚簇时，跳过极狠；随机值则 min/max 覆盖全域，等于没索引。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>B+ 精确定位键。zone map 只回答「这个 8MB 里有没有可能命中」。假阳性（区说可能有，实际没有）会多读；不应有假阴性（说没有却有）。缺口是维护：插入更新要调整 min/max；删除可能使 min 过时（仍安全，只是少跳过）或需重算。</p><p>与布隆：布隆服务等值「不在集合」；zone map 服务范围与比较。可同时存在。与直方图：直方图给优化器基数；zone map 给执行器跳 I/O。两者都是摘要，用途不同。</p><p><span class="marginnote">数字实例：1 TB 表切成 128 个 8 MB 的区，查 <code>amount \\gt 9900</code>。若各区 min/max 都有覆盖，得读全部 128 区；数据按金额聚簇后，min/max 显示只有 3 个区可能含 \\gt 9900 的行——125 个区连页都不碰，I/O 一步砍掉约 97%。</span></p><p><span class="marginnote">存储索引、small materialized aggregates、minmax 块索引是同一族。数据按时间插入则时间列 zone map 近乎分区裁剪。无序 UUID 列上 zone map 几乎无用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>粒度：页、extent、分区、row group。谓词下推到扫描：比较 zone 与常量。复合谓词：各列 zone 分别裁，AND 收紧。分区表：分区约束是声明的 zone（后课表分区）。</p><p>写入：原地更新若缩小值域仍可只放宽 min/max（保守）。VACUUM 后重建更紧。</p>',11)),(o(),i(s,null,{default:n(()=>[m(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E8%8C%83%E5%9B%B4%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20Z%5B%22%E5%8C%BA%20min%2Fmax%22%5D%0A%20%20Z%20--%3E%7C%22%E6%97%A0%E4%BA%A4%22%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E5%8C%BA%22%5D%0A%20%20Z%20--%3E%7C%22%E6%9C%89%E4%BA%A4%22%7C%20READ%5B%22%E8%AF%BB%E5%8C%BA%E5%86%8D%E7%B2%BE%E7%A1%AE%E8%BF%87%E6%BB%A4%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"向量化扫描前先丢区。并行工人按仍可能命中的区划分，避免空工人。优化器可用 zone 改善估计，但过期 zone 导致计划仍扫——执行仍会跳，估计与执行不一致又是回归源。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},'直觉类比：zone map 是一排仓库门口挂的告示牌："本仓存货温度在 -5 到 40 度"。你要找 50 度以上的货，看一眼牌子就知道整仓都不用进——牌子永远不会让你漏掉货（假阴性为零），但可能让你白进几间空跑（假阳性允许）。')],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},'常见误区：初学者容易以为"有 zone map 就一定快"。实际收益完全押在数据物理布局上：按插入时间或按查询列排序的表跳得极狠，随机 UUID 主键的表 min/max 覆盖全域，一行都跳不掉——索引没变，变的是数据是否配合。')],-1)),(o(),i(s,null,{default:n(()=>[m(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E8%B0%93%E8%AF%8D%20x%20BETWEEN%20100%20AND%20200%22%5D%20--%3E%20LOOP%7B%22%E8%BF%98%E6%9C%89%E6%9C%AA%E5%88%A4%E5%AE%9A%E7%9A%84%E5%8C%BA%22%7D%0A%20%20LOOP%20--%3E%20CMP%5B%22%E6%AF%94%E5%AF%B9%E8%B0%93%E8%AF%8D%E4%B8%8E%E5%8C%BA%20min%2Fmax%22%5D%0A%20%20CMP%20--%3E%20DIS%7B%22%E5%8C%BA%E9%97%B4%E6%9C%89%E4%BA%A4%E5%90%97%22%7D%0A%20%20DIS%20--%3E%20N%5B%22%E6%97%A0%E4%BA%A4%EF%BC%9A%E6%95%B4%E5%8C%BA%E8%B7%B3%E8%BF%87%22%5D%0A%20%20DIS%20--%3E%20Y%5B%22%E6%9C%89%E4%BA%A4%EF%BC%9A%E8%AF%BB%E5%8C%BA%E7%B2%BE%E7%A1%AE%E8%BF%87%E6%BB%A4%22%5D%0A%20%20N%20--%3E%20LOOP%0A%20%20Y%20--%3E%20LOOP%0A%20%20LOOP%20--%3E%7C%22%E5%85%A8%E9%83%A8%E5%8C%BA%E5%B7%B2%E5%88%A4%E5%AE%9A%22%7C%20DONE%5B%22%E8%BF%94%E5%9B%9E%E5%91%BD%E4%B8%AD%E8%A1%8C%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>LSM：SST 的 key range 是一种 zone；块内 min/max 更细。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲位图索引的逐值精确。也不把学习索引的模型当 zone。跳过失败不是 bug，是摘要粒度。</p><p>后课默认：扫描带 zone 裁剪；无序列不要指望 min/max。位图索引：低 NDV 列上精确存在测试，补 zone 的「可能」。</p><p>Zone 是执行侧过滤器，不是候选键。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>zone map 用 min/max 等摘要跳过不可能命中的区。</li><li>维护偏保守；无序列收益低。</li><li>位图索引下一课：低基数列的精确位向量。</li><li>出处：storage index 实践；C-Store；列文件统计。</li></ul>',7))])}const h=l(B,[["render",d]]);export{f as __pageData,h as default};
